#!/usr/bin/env bash
set -euo pipefail

CONFIG_NAME="${CONFIG_NAME:-star_math_solver_verifier_refiner_finalizer_trainer}"

PROJECT_NAME="${PROJECT_NAME:-star_math_multi_agent}"
EXPERIMENT_NAME="${EXPERIMENT_NAME:-solver_verifier_refiner_finalizer_qwen2_5_7b}"

AGENT_MODEL_PATH="${AGENT_MODEL_PATH:-${UNITYMAS_ROOT:?Set UNITYMAS_ROOT}/base_models/Qwen/Qwen2.5-7B-Instruct}"
TRAIN_JSONL="${TRAIN_JSONL:-${UNITYMAS_ROOT:?Set UNITYMAS_ROOT}/datasets/Math/DAPO-Math-17k/data/dapo-math-17k.question.jsonl}"
VAL_FILES="${VAL_FILES:-${VAL_JSONL:-}}"
VAL_FILES="${VAL_FILES:-${UNITYMAS_ROOT:?Set UNITYMAS_ROOT}/datasets/Math/MATH-500/test.jsonl}"

NNODES="${NNODES:-4}"
GPUS_PER_NODE="${GPUS_PER_NODE:-8}"
AGENT_GPUS_PER_NODE="${AGENT_GPUS_PER_NODE:-8}"
SHARED_LLM_NNODES="${SHARED_LLM_NNODES:-2}"

GEN_BATCH_SIZE="${GEN_BATCH_SIZE:-128}"
VAL_BATCH_SIZE="${VAL_BATCH_SIZE:-128}"
ACTOR_PPO_MINI_BATCH_SIZE="${ACTOR_PPO_MINI_BATCH_SIZE:-64}"
ACTOR_PPO_MICRO_BATCH_SIZE_PER_GPU="${ACTOR_PPO_MICRO_BATCH_SIZE_PER_GPU:-2}"
CRITIC_PPO_MICRO_BATCH_SIZE_PER_GPU="${CRITIC_PPO_MICRO_BATCH_SIZE_PER_GPU:-2}"
ADV_ESTIMATOR="${ADV_ESTIMATOR:-gae}"
USE_REMOVE_PADDING="${USE_REMOVE_PADDING:-true}"
ULYSSES_SEQUENCE_PARALLEL_SIZE="${ULYSSES_SEQUENCE_PARALLEL_SIZE:-4}"
ENABLE_ACTIVATION_OFFLOAD="${ENABLE_ACTIVATION_OFFLOAD:-false}"
FSDP_PARAM_OFFLOAD="${FSDP_PARAM_OFFLOAD:-false}"
FSDP_OPTIMIZER_OFFLOAD="${FSDP_OPTIMIZER_OFFLOAD:-false}"
FSDP_OFFLOAD_POLICY="${FSDP_OFFLOAD_POLICY:-false}"

ROLLOUT_PROMPT_LENGTH="${ROLLOUT_PROMPT_LENGTH:-8192}"
ROLLOUT_RESPONSE_LENGTH="${ROLLOUT_RESPONSE_LENGTH:-4096}"
ROLLOUT_MAX_MODEL_LEN="${ROLLOUT_MAX_MODEL_LEN:-16384}"
ROLLOUT_TENSOR_MODEL_PARALLEL_SIZE="${ROLLOUT_TENSOR_MODEL_PARALLEL_SIZE:-2}"
ROLLOUT_GPU_MEMORY_UTILIZATION="${ROLLOUT_GPU_MEMORY_UTILIZATION:-0.70}"

VAL_BEFORE_TRAIN="${VAL_BEFORE_TRAIN:-true}"
TEST_FREQ="${TEST_FREQ:-50}"
SAVE_FREQ="${SAVE_FREQ:-300}"
TOTAL_EPOCHS="${TOTAL_EPOCHS:-10}"
TOTAL_TRAINING_STEPS="${TOTAL_TRAINING_STEPS:-}"
CKPTS_DIR="${CKPTS_DIR:-${UNITYMAS_ROOT:?Set UNITYMAS_ROOT}/ckpts/${PROJECT_NAME}/${EXPERIMENT_NAME}}"

cmd=(
  python3 -m verl.experimental.star_ppo.main_ppo
  --config-name "${CONFIG_NAME}"
  "trainer.project_name=${PROJECT_NAME}"
  "trainer.experiment_name=${EXPERIMENT_NAME}"
  "trainer.nnodes=${NNODES}"
  "trainer.n_gpus_per_node=${GPUS_PER_NODE}"
  "trainer.logger=[console,wandb]"
  "trainer.val_before_train=${VAL_BEFORE_TRAIN}"
  "trainer.test_freq=${TEST_FREQ}"
  "trainer.save_freq=${SAVE_FREQ}"
  "trainer.total_epochs=${TOTAL_EPOCHS}"
  "trainer.default_local_dir=${CKPTS_DIR}"
  "trainer.llm_engines.0.model_path=${SOLVER_VERIFIER_MODEL_PATH:-${SOLVER_MODEL_PATH:-${AGENT_MODEL_PATH}}}"
  "trainer.llm_engines.1.model_path=${REFINER_FINALIZER_MODEL_PATH:-${REFINER_MODEL_PATH:-${AGENT_MODEL_PATH}}}"
  "trainer.llm_engines.0.nnodes=${SOLVER_VERIFIER_NNODES:-${SHARED_LLM_NNODES}}"
  "trainer.llm_engines.1.nnodes=${REFINER_FINALIZER_NNODES:-${SHARED_LLM_NNODES}}"
  "trainer.llm_engines.0.n_gpus_per_node=${SOLVER_VERIFIER_GPUS_PER_NODE:-${SOLVER_GPUS_PER_NODE:-${AGENT_GPUS_PER_NODE}}}"
  "trainer.llm_engines.1.n_gpus_per_node=${REFINER_FINALIZER_GPUS_PER_NODE:-${REFINER_GPUS_PER_NODE:-${AGENT_GPUS_PER_NODE}}}"
  "actor_rollout_ref.model.path=${SOLVER_VERIFIER_MODEL_PATH:-${SOLVER_MODEL_PATH:-${AGENT_MODEL_PATH}}}"
  "data.train_files=${TRAIN_JSONL}"
  "data.val_files=${VAL_FILES}"
  "data.gen_batch_size=${GEN_BATCH_SIZE}"
  "data.train_batch_size=${GEN_BATCH_SIZE}"
  "data.val_batch_size=${VAL_BATCH_SIZE}"
  "actor_rollout_ref.actor.ppo_mini_batch_size=${ACTOR_PPO_MINI_BATCH_SIZE}"
  "actor_rollout_ref.actor.ppo_micro_batch_size_per_gpu=${ACTOR_PPO_MICRO_BATCH_SIZE_PER_GPU}"
  "critic.ppo_micro_batch_size_per_gpu=${CRITIC_PPO_MICRO_BATCH_SIZE_PER_GPU}"
  "algorithm.adv_estimator=${ADV_ESTIMATOR}"
  "actor_rollout_ref.model.use_remove_padding=${USE_REMOVE_PADDING}"
  "critic.model.use_remove_padding=${USE_REMOVE_PADDING}"
  "actor_rollout_ref.actor.ulysses_sequence_parallel_size=${ULYSSES_SEQUENCE_PARALLEL_SIZE}"
  "actor_rollout_ref.ref.ulysses_sequence_parallel_size=${ULYSSES_SEQUENCE_PARALLEL_SIZE}"
  "critic.ulysses_sequence_parallel_size=${ULYSSES_SEQUENCE_PARALLEL_SIZE}"
  "actor_rollout_ref.actor.fsdp_config.ulysses_sequence_parallel_size=${ULYSSES_SEQUENCE_PARALLEL_SIZE}"
  "actor_rollout_ref.ref.fsdp_config.ulysses_sequence_parallel_size=${ULYSSES_SEQUENCE_PARALLEL_SIZE}"
  "critic.model.fsdp_config.ulysses_sequence_parallel_size=${ULYSSES_SEQUENCE_PARALLEL_SIZE}"
  "actor_rollout_ref.model.enable_activation_offload=${ENABLE_ACTIVATION_OFFLOAD}"
  "critic.model.enable_activation_offload=${ENABLE_ACTIVATION_OFFLOAD}"
  "actor_rollout_ref.actor.fsdp_config.param_offload=${FSDP_PARAM_OFFLOAD}"
  "actor_rollout_ref.actor.fsdp_config.optimizer_offload=${FSDP_OPTIMIZER_OFFLOAD}"
  "actor_rollout_ref.actor.fsdp_config.offload_policy=${FSDP_OFFLOAD_POLICY}"
  "critic.model.fsdp_config.param_offload=${FSDP_PARAM_OFFLOAD}"
  "critic.model.fsdp_config.optimizer_offload=${FSDP_OPTIMIZER_OFFLOAD}"
  "critic.model.fsdp_config.offload_policy=${FSDP_OFFLOAD_POLICY}"
  "actor_rollout_ref.rollout.prompt_length=${ROLLOUT_PROMPT_LENGTH}"
  "actor_rollout_ref.rollout.response_length=${ROLLOUT_RESPONSE_LENGTH}"
  "actor_rollout_ref.rollout.max_model_len=${ROLLOUT_MAX_MODEL_LEN}"
  "actor_rollout_ref.rollout.tensor_model_parallel_size=${ROLLOUT_TENSOR_MODEL_PARALLEL_SIZE}"
  "actor_rollout_ref.rollout.gpu_memory_utilization=${ROLLOUT_GPU_MEMORY_UTILIZATION}"
)

if [[ -n "${TOTAL_TRAINING_STEPS}" ]]; then
  cmd+=("trainer.total_training_steps=${TOTAL_TRAINING_STEPS}")
fi

"${cmd[@]}" "$@"
